mapper.select:
SELECT a.abnormal_id as id, a.abnormal_type as abnormalType, a.related_no as relatedNo, CASE a.abnormal_type WHEN 'duplicate' THEN a.related_no WHEN 'refund' THEN a.related_no WHEN 'escrow' THEN a.related_no WHEN 'settlement' THEN a.related_no END as displayNo, -- 重复支付专用字段 CASE WHEN a.abnormal_type = 'duplicate' THEN a.related_no END as orderNo, CASE WHEN a.abnormal_type = 'duplicate' THEN u.nick_name END as userName, CASE WHEN a.abnormal_type = 'duplicate' THEN a.abnormal_amount END as duplicateAmount, a.duplicate_count as duplicateCount, -- 退款异常专用字段 CASE WHEN a.abnormal_type = 'refund' THEN a.related_no END as refundNo, CASE WHEN a.abnormal_type = 'refund' THEN a.abnormal_amount END as refundAmount, -- 托管异常专用字段 CASE WHEN a.abnormal_type = 'escrow' THEN a.related_no END as escrowNo, CASE WHEN a.abnormal_type = 'escrow' THEN a.abnormal_amount END as escrowAmount, -- 结算异常专用字段 CASE WHEN a.abnormal_type = 'settlement' THEN a.related_no END as settlementNo, CASE WHEN a.abnormal_type = 'settlement' THEN (SELECT nick_name FROM sys_user WHERE user_id = a.user_id) END as authorName, CASE WHEN a.abnormal_type = 'settlement' THEN a.abnormal_amount END as settlementAmount, -- 通用字段 a.abnormal_amount as abnormalAmount, a.abnormal_reason as abnormalReason, a.abnormal_desc as abnormalDesc, a.status, a.handle_solution as handleSolution, a.handle_remark as handleRemark, DATE_FORMAT(a.create_time, '%Y-%m-%d %H:%i') as createTime, DATE_FORMAT(a.handle_time, '%Y-%m-%d %H:%i') as handleTime FROM sys_finance_abnormal a LEFT JOIN sys_user u ON a.user_id = u.user_id
AND a.abnormal_type = #{type}
AND a.status = #{status}
AND (a.related_no LIKE CONCAT('%', #{keyword}, '%') OR u.nick_name LIKE CONCAT('%', #{keyword}, '%'))
ORDER BY a.create_time DESC LIMIT #{offset}, #{limit}

SELECT COUNT(*) FROM sys_finance_abnormal a LEFT JOIN sys_user u ON a.user_id = u.user_id
AND a.abnormal_type = #{type}
AND a.status = #{status}
AND (a.related_no LIKE CONCAT('%', #{keyword}, '%') OR u.nick_name LIKE CONCAT('%', #{keyword}, '%'))
